    stream: { role: "streamMember" },
    authoring: { unit: "inline", bag: "organization" },
    parents: [],
    resource: { shape: "none" },
    data: NO_DATA,
    lifecycle: {
        participates: true,
        toTf: (entity, ctx) => ({
            blocks: organizationToTf(entity.payload, {
                orgRefs: ctx.orgRefs,
                diagnostics: ctx.diagnostics,
            }),
        }),
    },
    canvas: NO_CANVAS,
    catalog: NO_CATALOG,
